std::atomic<unsigned> c{0};
for (int i = 0; i < 5; ++i) bumpRelaxed(c);
CHECK_EQ(c.load(), 5u);

std::atomic<bool> f{false};
int v = 0;
publishAndSpin(f, v, 99);
CHECK_EQ(consumeAfter(f, v), 99);
